export function flattenResults(results){if(results.length===0){return{text:"",results:[],confidence:0}}let text=results.map((r)=>r.text).join(" ");let avgConfidence=results.reduce((sum,r)=>sum+r.confidence,0)/results.length;return{text,results,confidence:avgConfidence}}export function groupResultsByLine(results){if(results.length===0){return{text:"",lines:[],confidence:0}}let lines=[];let currentLine=[];let firstResult=results[0];if(!firstResult)return{text:"",lines:[],confidence:0};let currentY=firstResult.box.y;let avgHeight=firstResult.box.height;for(let result of results){const{box}=result;if(Math.abs(box.y-currentY)<avgHeight/2){currentLine.push(result);avgHeight=(avgHeight*(currentLine.length-1)+box.height)/currentLine.length}else{currentLine.sort((a,b)=>a.box.x-b.box.x);lines.push(currentLine);currentLine=[result];currentY=box.y;avgHeight=box.height}}if(currentLine.length>0){currentLine.sort((a,b)=>a.box.x-b.box.x);lines.push(currentLine)}let fullText=lines.map((line)=>line.map((r)=>r.text).join(" ")).join(`
`);let totalConfidence=lines.reduce((sum,line)=>sum+line.reduce((s,r)=>s+r.confidence,0),0);let totalItems=lines.reduce((sum,line)=>sum+line.length,0);return{text:fullText,lines,confidence:totalItems>0?totalConfidence/totalItems:0}}export function groupBoxesIntoLines(boxes){if(boxes.length===0)return[];let sorted=[...boxes].sort((a,b)=>a.box.y-b.box.y||a.box.x-b.box.x);let lines=[];let firstSorted=sorted[0];if(!firstSorted)return[];let currentLine=[firstSorted];let currentLineHeightSum=firstSorted.box.height;let avgHeight=firstSorted.box.height;for(let i=1;i<sorted.length;i++){let current=sorted[i];let previous=sorted[i-1];if(!current||!previous)continue;let verticalGap=Math.abs(current.box.y-previous.box.y);let threshold=avgHeight*0.5;if(verticalGap<=threshold){currentLine.push(current);currentLineHeightSum+=current.box.height;avgHeight=currentLineHeightSum/currentLine.length}else{currentLine.sort((a,b)=>a.box.x-b.box.x);lines.push(currentLine);currentLine=[current];currentLineHeightSum=current.box.height;avgHeight=current.box.height}}if(currentLine.length>0){currentLine.sort((a,b)=>a.box.x-b.box.x);lines.push(currentLine)}return lines}let MAX_BOX_STRETCH=4;let MAX_MERGED_WIDTH=16384;export function mergeLineCrop(sourceCanvas,lineBoxes,createCanvas,canvasOps){let minX=Math.min(...lineBoxes.map((b)=>b.box.x));let minY=Math.min(...lineBoxes.map((b)=>b.box.y));let maxRight=Math.max(...lineBoxes.map((b)=>b.box.x+b.box.width));let maxBottom=Math.max(...lineBoxes.map((b)=>b.box.y+b.box.height));let mergedBox={x:minX,y:minY,width:maxRight-minX,height:maxBottom-minY};let commonHeight=maxBottom-minY;let gap=Math.max(1,Math.round(commonHeight*0.4));let widths=lineBoxes.map(({box})=>Math.max(1,Math.round(box.width*Math.min(commonHeight/box.height,MAX_BOX_STRETCH))));let totalWidth=widths.reduce((sum,w)=>sum+w,0)+gap*(lineBoxes.length-1);if(totalWidth>MAX_MERGED_WIDTH){let shrink=MAX_MERGED_WIDTH/totalWidth;widths=widths.map((w)=>Math.max(1,Math.round(w*shrink)));gap=Math.max(1,Math.floor(gap*shrink))}let commonWidth=widths.reduce((sum,w)=>sum+w,0)+gap*(lineBoxes.length-1);let mergedCanvas=createCanvas(commonWidth,commonHeight);let ctx=mergedCanvas.getContext("2d");ctx.fillStyle="white";ctx.fillRect(0,0,commonWidth,commonHeight);let offsetX=0;let cropWidths=[];for(let i=0;i<lineBoxes.length;i++){let entry=lineBoxes[i];let stretchedWidth=widths[i];if(!entry||stretchedWidth===undefined)continue;const{box}=entry;let cropped=canvasOps.getToolkit().crop({bbox:{x0:box.x,y0:box.y,x1:box.x+box.width,y1:box.y+box.height},canvas:sourceCanvas});ctx.drawImage(cropped,0,0,box.width,box.height,offsetX,0,stretchedWidth,commonHeight);let trailingGap=i<lineBoxes.length-1?gap:0;cropWidths.push(stretchedWidth+trailingGap);offsetX+=stretchedWidth+trailingGap}return{mergedCanvas,mergedBox,cropWidths}}export function splitTextByPositions(text,positions,segmentWidths){let chars=[...text];if(positions.length!==chars.length||segmentWidths.length===0){return splitBatchTextByWidths(text,segmentWidths)}let totalWidth=segmentWidths.reduce((a,b)=>a+b,0);let result=segmentWidths.map(()=>"");let seg=0;let segEnd=(segmentWidths[0]??0)/totalWidth;for(let i=0;i<chars.length;i++){let pos=positions[i]??0;while(pos>=segEnd&&seg<segmentWidths.length-1){seg++;segEnd+=(segmentWidths[seg]??0)/totalWidth}result[seg]+=chars[i]??""}return result}let CUT_SNAP_RANGE=4;export function splitBatchTextByWidths(text,cropWidths){if(cropWidths.length===1){return[text]}let totalWidth=cropWidths.reduce((a,b)=>a+b,0);let chars=[...text];let charWidth=chars.length>0?totalWidth/chars.length:0;let result=[];let charIdx=0;for(let i=0;i<cropWidths.length;i++){if(i===cropWidths.length-1){result.push(chars.slice(charIdx).join(""));break}let ideal=Math.min(charIdx+Math.round((cropWidths[i]??0)/charWidth),chars.length);let cut=ideal;let skipSpace=false;for(let d=0;d<=CUT_SNAP_RANGE&&!skipSpace;d++){for(let cand of[ideal-d,ideal+d]){let ch=chars[cand];if(cand>charIdx&&cand<chars.length&&ch!==undefined&&/\s/.test(ch)){cut=cand;skipSpace=true;break}}}result.push(chars.slice(charIdx,cut).join(""));charIdx=skipSpace?cut+1:cut}return result}export function packIntoBatches(items,widthOf,targetWidth,separatorGap){let sorted=[...items].sort((a,b)=>widthOf(b)-widthOf(a));let batches=[];let widths=[];for(let item of sorted){let placed=false;for(let b=0;b<batches.length;b++){let batch=batches[b];let width=widths[b];if(batch===undefined||width===undefined)continue;let gap=separatorGap*batch.length;if(width+gap+widthOf(item)<=targetWidth){batch.push(item);widths[b]=width+widthOf(item);placed=true;break}}if(!placed){batches.push([item]);widths.push(widthOf(item))}}return batches}